// GENERATED by tools/amx40-source-bake.py from the owner-supplied AMX-40.
// Do not hand-edit the encoded arrays. Donor tracks/wheels are intentionally
// absent; france.js retains the fleet-native animated six-wheel system.
import * as THREE from 'three';

const DATA = {
  hull: { p: '', i: '' },
  hullDetail: { p: '', i: '' },
  turret: { p: '', i: '' },
  turretDetail: { p: '', i: '' },
  gun: { p: '', i: '' },
};

const TURRET_PIVOT = [-0.001, 1.545, -0.421];
const GUN_WORLD_PIVOT = [0.0, 1.94, 1.30];

function bytes(s) {
  const raw = atob(s);
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
  return out;
}

function geometry(row) {
  if (!row.positions) {
    const pb = bytes(row.p), ib = bytes(row.i);
    row.positions = new Float32Array(
      pb.buffer, pb.byteOffset, pb.byteLength / 4);
    row.indices = new Uint32Array(
      ib.buffer, ib.byteOffset, ib.byteLength / 4);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(row.positions, 3));
  g.setIndex(new THREE.BufferAttribute(row.indices, 1));
  g.computeVertexNormals();
  const p = g.attributes.position, n = g.attributes.normal;
  const uv = new Float32Array(p.count * 2);
  for (let k = 0; k < p.count; k++) {
    const nx = Math.abs(n.getX(k)), ny = Math.abs(n.getY(k));
    const nz = Math.abs(n.getZ(k));
    let u, v;
    if (ny >= nx && ny >= nz) { u = p.getX(k); v = p.getZ(k); }
    else if (nx >= nz) { u = p.getZ(k); v = p.getY(k); }
    else { u = p.getX(k); v = p.getY(k); }
    uv[k * 2] = u * 0.35;
    uv[k * 2 + 1] = v * 0.35;
  }
  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  return g;
}

export function buildAMX40SourceGeometry(P) {
  P.turretG.position.fromArray(TURRET_PIVOT);
  P.gunG.position.set(
    GUN_WORLD_PIVOT[0] - TURRET_PIVOT[0],
    GUN_WORLD_PIVOT[1] - TURRET_PIVOT[1],
    GUN_WORLD_PIVOT[2] - TURRET_PIVOT[2],
  );
  P.add('hull', geometry(DATA.hull));
  P.add('hullDetail', geometry(DATA.hullDetail));
  P.add('turret', geometry(DATA.turret));
  P.add('turretDetail', geometry(DATA.turretDetail));
  P.add('gun', geometry(DATA.gun));

  // The exact source supplies its roof weapon and coax. Preserve the fitting
  // census without drawing duplicate procedural weapons.
  const mgMarker = new THREE.Group();
  mgMarker.name = 'fitting_amx40SourceRoofWeapon';
  mgMarker.userData.fittingRoot = true;
  mgMarker.userData.fitting = 'pintleMG';
  P.turretG.add(mgMarker);
  P.muzzleZ = 5.322;
  P.topY = 1.261;
}
